import{_ as i,C as r,o as n,c as s,j as t,a as c,E as e,ak as a}from"./chunks/framework.DxrHb2fb.js";const v=JSON.parse('{"title":"TagGroup 标签组","description":"","frontmatter":{},"headers":[],"relativePath":"components/tag-group.md","filePath":"components/tag-group.md","lastUpdated":1789930800000}'),h={name:"components/tag-group.md"},g={id:"taggroup-标签组",tabindex:"-1"};function b(u,d,p,m,f,x){const l=r("Badge"),o=r("XhDemo");return n(),s("div",null,[t("h1",g,[d[0]||(d[0]=c("TagGroup 标签组 ",-1)),e(l,{type:"info",text:"alpha"}),d[1]||(d[1]=c()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#taggroup-标签组","aria-label":'Permalink to "TagGroup 标签组 <Badge type="info" text="alpha" />"'},"​",-1))]),d[3]||(d[3]=a('<p>把一排标签作为一个整体操作：方向键在标签之间移动，整组只占一个 Tab 停靠点，标签可以选中、也可以移除，移除后焦点有去处。</p><p>单个<a href="./tag">标签</a>不接收焦点，它的关闭按钮是页面上一个独立的 Tab 停靠点：十个标签就是十个停靠点，键盘用户需要按十次才能越过。标签组把这十个收成一个。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/tag-group" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/tag-group.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/tag-group" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/tag-group" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/tag-group.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一排可移除标签，每个都是库内的 tag：整组只占一个 Tab 位，方向键移动标签，Delete 或 Backspace 移除，关闭按钮就是 tag 的 close-trigger</p>',5)),e(o,{src:"tag-group/01-basic"}),d[4]||(d[4]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;tag-group&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>list</code></strong> · <strong><code>cell</code></strong> · <code>item-indicator</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="可选中" tabindex="-1">可选中 <a class="header-anchor" href="#可选中" aria-label="Permalink to &quot;可选中&quot;">​</a></h3><p>selectionMode 决定点击一个标签是替换还是加选；Ctrl/Cmd + A 全选</p>',6)),e(o,{src:"tag-group/02-selection"}),d[5]||(d[5]=t("h3",{id:"尺寸",tabindex:"-1"},[c("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[6]||(d[6]=t("p",null,"size 写在组上逐个落到每个标签上，使用 tag 的三档，标签自身不写档位",-1)),e(o,{src:"tag-group/03-size"}),d[7]||(d[7]=t("h3",{id:"手写部件",tabindex:"-1"},[c("手写部件 "),t("a",{class:"header-anchor",href:"#手写部件","aria-label":'Permalink to "手写部件"'},"​")],-1)),d[8]||(d[8]=t("p",null,"逐部件自行编写，标签中即可放置头像、计数等自带内容，移除按钮照常归 cell 管理；条目渲染为 tag 的 root、文字是 tag 的 label，产出的结构与只提供数据的一份完全一致，Tab 位与键盘也一样",-1)),e(o,{src:"tag-group/04-parts"}),d[9]||(d[9]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>一排可移除的标签：已生效的筛选条件、一条记录关联的若干分类。</li><li>一排可选的标记：点击一个即筛选一次，或按住多选。</li><li>键盘与读屏用户需要逐个遍历、逐个移除。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>只有一个标签且不接受交互时，直接使用<a href="./tag">标签</a>。</li><li>用户需要自行输入并累积多个值时，使用<a href="./tags-input">标签输入</a>，它自带输入框与增删逻辑。</li><li>选项很多、需要搜索时，使用<a href="./select">选择器</a>的多选或<a href="./transfer">穿梭框</a>。</li><li>一组互斥选项需要用户选一个时，使用<a href="./radio-group">单选组</a>或<a href="./segmented">分段控制器</a>。</li><li>只是把一排标签排开、不接键盘时，用<a href="./flex">弹性布局</a>包一层即可。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>roving tabindex：整组一个 Tab 停靠点，组内使用方向键移动；<code>Home</code> / <code>End</code> 到端点。</li><li><code>selectionMode</code> 三档：<code>none</code> 只是标记、<code>single</code> 单选、<code>multiple</code> 可多选（<code>Ctrl</code> / <code>Cmd</code> + <code>A</code> 全选）。</li><li>每一个标签就是库内的<a href="./tag">标签</a>：标签本体是它的 <code>root</code>，文字是它的 <code>label</code>，移除按钮是它的 <code>close-trigger</code>；组只在其上叠加行角色、Tab 停靠点、选中与锚点。</li><li>选中的标签使用品牌淡底，并在文字前展示 <code>item-indicator</code> 选中标记（默认绘制对号，也可放入图标）；未选中时该部件收起，不接选中时不出现。</li><li><code>deletable</code> 显示移除按钮，键盘路径使用 <code>Delete</code> / <code>Backspace</code>。</li><li>选择与移除是两个互斥动作：点击标签本体才选择，点击移除按钮只从选中集合移除并发出 <code>item-delete</code>，不会让同一次冒泡 click 把待删值重新选中。</li><li>移除一个之后焦点交给前一个；前面没有则交给后一个，没有剩余时交给列表容器。</li><li><code>collection</code> 是文本、禁用与可移除的事实源；也可以逐个编写。</li><li>连续输入按首字母跳转，只移动焦点、不改变选中值。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>每一个标签就是<a href="./tag">标签</a>本身：形态、语气、尺寸三轴写在组上，逐个落到每个标签的 <code>root</code>，外观全部由 <code>tag.css</code> 决定，<code>--xh-tag-*</code> 覆盖槽在组内同样生效。</li><li>标签内的图元使用<a href="./icon">图标</a>。</li><li>外层放<a href="./field">表单字段</a>，为标题提供位置。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>条目的去留由宿主决定：<code>item-delete</code> 只报告用户要移除哪一个，宿主从自己的数据中删除。撤销、二次确认、服务端失败回滚都只有宿主知道。</li><li>移除之后提供回退路径，否则用户误点后无法恢复。</li><li>标签文字尽量短，且首字母有区分度：连续输入按首字母跳转。</li><li>不接选中时把 <code>selectionMode</code> 保持为 <code>none</code>：一排纯标记标签报告“未选中”是错误信息。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>把整排标签铺成十个 Tab 停靠点：这正是本组件要解决的问题，不再逐个编写<a href="./tag">标签</a>。</li><li>移除后不处理焦点：被移除的标签带着焦点一起消失，焦点会回到页面开头。</li><li>只用颜色表达含义：色觉障碍的用户无法分辨，文字本身要说明。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tag-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTagGroupCell</code> <code>XhTagGroupItem</code> <code>XhTagGroupItemDeleteTrigger</code> <code>XhTagGroupItemIndicator</code> <code>XhTagGroupItemText</code> <code>XhTagGroupLabel</code> <code>XhTagGroupList</code> <code>XhTagGroupRoot</code></td></tr><tr><td>组合式函数</td><td><code>useTagGroup</code></td></tr><tr><td>状态机</td><td><code>tagGroupMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tag-group.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>TagGroupNode[]</code></td><td></td><td>条目数据，显示文本、禁用与可移除的事实源。提供后条目部件只需声明 value。 未提供时回到文本与禁用都写在条目部件上的方式。</td></tr><tr><td><code>value</code></td><td><code>string | string[]</code></td><td></td><td>选中值，提供即受控；单选可写为裸串，内部归一为数组。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | string[]</code></td><td></td><td></td></tr><tr><td><code>selectionMode</code></td><td><code>TagGroupSelectionMode</code></td><td></td><td>选择模式，默认 none。</td></tr><tr><td><code>deletable</code></td><td><code>boolean</code></td><td></td><td>是否提供移除按钮，默认 false。false 时该按钮同时被禁用与收起。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组禁用：键盘与点击都不再修改选中值，也不可移除任何标签。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：仍可聚焦、可导航与朗读，但选中值不可修改、标签也不可移除。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键到达末尾是否回绕，默认 true。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 horizontal：标签成排出现。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>连打检索，默认开启。</td></tr><tr><td><code>variant</code></td><td><code>TagVariant</code></td><td></td><td>形态：solid / subtle / outline，逐个写到每个标签（tag 的 root）上。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，使用 tag 的三档。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: TagGroupValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调。</td></tr><tr><td><code>onItemDelete</code></td><td><code>(details: TagGroupItemDeleteDetails) =&gt; void</code></td><td></td><td>移除意图回调。条目由宿主的数据决定去留，组件只报告用户要移除该标签， 同时把它从选中集合中移除，并把焦点交给相邻的标签。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TagGroupTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>TagGroupValueChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>item-delete</code></td><td><code>TagGroupItemDeleteDetails</code></td><td>用户要移除某个标签；detail 为 <code>{ value: string }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTagGroupRoot</code></td><td><code>default</code></td><td><code>TagGroupRootSlotProps</code></td><td></td></tr><tr><td><code>XhTagGroupRoot</code></td><td><code>label</code></td><td>—</td><td></td></tr><tr><td><code>XhTagGroupRoot</code></td><td><code>item</code></td><td><code>TagGroupNodeMeta</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.TOGGLE</code> · <code>ITEM.FOCUS</code> · <code>ITEM.DELETE</code> · <code>LIST.BLUR</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string[]</code></td><td>选中集合；单选模式下长度 ≤ 1。</td></tr><tr><td><code>collection</code></td><td><code>readonly TagGroupNodeMeta[]</code></td><td>由 collection 推导的条目元信息，按数据顺序排列；未提供 collection 时为空数组。</td></tr><tr><td><code>selectionMode</code></td><td><code>TagGroupSelectionMode</code></td><td>生效的选择模式。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；焦点不在组内时为 null。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>deletable</code></td><td><code>boolean</code></td><td>整组是否提供移除按钮。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td>只保留该条目；加选使用 toggle。</td></tr><tr><td><code>toggle</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>deleteItem</code></td><td><code>(value: string) =&gt; void</code></td><td>移除一个标签。程序化入口，不移动焦点。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>一个标签：库内 tag 的 root（data-scope=&quot;tag&quot;），三轴与置灰由 tag 提供； row 角色、身份、roving tabindex、选中（data-selected）与锚点（data-highlighted）叠加在它上面。</td></tr><tr><td><code>getCellProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>标签内的格子；移除按钮必须落在它之内。</td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>选中标记：落在格子内、文字之前，选中时展示、未选中时以 hidden 收起； 对读屏隐藏，选中态由标签上的 aria-selected 表达。内容留空时由皮肤绘制对号，也可放入图标。</td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td>标签文字：tag 的 label，截断规则挂在该层。</td></tr><tr><td><code>getItemDeleteTriggerProps</code></td><td><code>(props: TagGroupItemProps) =&gt; T[&#39;button&#39;]</code></td><td>移除按钮：所在标签那份 tag 的 close-trigger，不占 Tab 位；可及名、禁用与收起都由 tag 提供。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/grid/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点标签，无锚点时先落到列表容器再由它转移；每个标签的移除按钮一律不占停靠点</td></tr><tr><td><code>ArrowRight</code></td><td>focus in group, orientation=horizontal</td><td>焦点移到下一个可停留标签（禁用项跳过、尽头按 loop 回绕）；orientation=vertical 时改由 ArrowDown 承担，dir=rtl 再对调左右</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in group, orientation=horizontal</td><td>焦点移到上一个可停留标签（禁用项跳过、尽头按 loop 回绕）；orientation=vertical 时改由 ArrowUp 承担，dir=rtl 再对调左右</td></tr><tr><td><code>Home</code></td><td>focus in group</td><td>焦点移到首枚可停留标签</td></tr><tr><td><code>End</code></td><td>focus in group</td><td>焦点移到末枚可停留标签</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, selectionMode=single 且可改</td><td>只选中焦点标签，替换原有选中；标签禁用或整组只读则不认</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, selectionMode=multiple 且可改</td><td>切换焦点标签的选中态，其余选中不动</td></tr><tr><td><code>Ctrl+A</code> / <code>Cmd+A</code></td><td>focus in group, selectionMode=multiple 且可改</td><td>选中全部可选标签；已经全选则把它们一并取消（禁用但已选中的不动）</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>focus on item, 该标签可移除且可修改</td><td>移除焦点标签，并把焦点交给前一个；前面没有则交给后一个，全部移除后交给列表容器</td></tr><tr><td><code>单个可打印字符</code></td><td>focus in group, typeahead 未关</td><td>连打检索把焦点移到首字母匹配的标签，不改选中值</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>aria-label</code></td><td>label.list</td></tr><tr><td><code>list</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>list</code></td><td><code>aria-multiselectable</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;grid&#39;</td></tr><tr><td><code>cell</code></td><td><code>role</code></td><td>&#39;gridcell&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39; | undefined</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;row&#39;</td></tr></tbody></table><p>一排可移除的标签是“集合 + 每条自带动作”，在 ARIA 中只有表格语义能容纳：可聚焦的移除按钮不允许位于 <code>option</code> 等控件角色内，<code>gridcell</code> 允许。因此 <code>list</code> 是 <code>grid</code>、每个标签（<a href="./tag">标签</a>的 <code>root</code>）承担 <code>row</code>、标签内的格是 <code>gridcell</code>；手写部件时 <code>cell</code> 这一层不能省略，使用 <code>collection</code> 时由组件铺开。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/tag-group.css</code> 使用 <code>[data-scope=&quot;tag-group&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>list</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>list</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>cell</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>cell</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>cell</code></td><td><code>data-selected</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-indicator</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-indicator</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-indicator</code></td><td><code>data-selected</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-deletable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-selectable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-selected</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-tag-group-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>tag-group 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-hover</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>highlighted</code><br><code>is(:hover, [data-highlighted])</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>tone</code><br><code>variant=solid</code></td><td><code>--xh-_tone-subtle-hover</code><br><code>--xh-bg-subtle</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-pressed</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>pressed</code><br><code>selectable</code><br><code>tone</code><br><code>variant=solid</code></td><td><code>--xh-_tone-subtle-active</code><br><code>--xh-bg-subtle-hover</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-pressed-solid</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>pressed</code><br><code>selectable</code><br><code>tone</code><br><code>variant=solid</code></td><td><code>--xh-_tone-active</code><br><code>--xh-bg-brand-active</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-selected</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone-subtle</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-selected-hover</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>highlighted</code><br><code>is(:hover, [data-highlighted])</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone-subtle-hover</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-bg-selected-pressed</code></td><td><code>list</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>pressed</code><br><code>selectable</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone-subtle-active</code></td><td>tag-group 的 list、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-border-selected</code></td><td><code>list</code><br><code>root</code></td><td><code>border-color</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>currentColor</code><br><code>transparent</code></td><td>tag-group 的 list、root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-fg-selected</code></td><td><code>list</code><br><code>root</code></td><td><code>color</code></td><td><code>disabled</code><br><code>not([data-disabled])</code><br><code>not([data-variant=&#39;solid&#39;])</code><br><code>selected</code><br><code>variant=solid</code></td><td><code>--xh-_tone-fg</code></td><td>tag-group 的 list、root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-indicator-fg</code></td><td><code>item-indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>currentColor</code></td><td>tag-group 的 item-indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-item-indicator-size</code></td><td><code>item-indicator</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>tag-group 的 item-indicator 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>tag-group 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>tag-group 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>tag-group 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-tag-group-list-gap</code></td><td><code>list</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1_5</code></td><td>tag-group 的 list 部件 gap 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p>',53))])}const P=i(h,[["render",b]]);export{v as __pageData,P as default};
